// Function Overloading Resolution (C++ Standard 13.4)

void write(int v);             // S1: int
void write(double v);          // S2: double
void write(int& v);            // S3: int&

int x = 10;
int& r = x;

write(x);       // Resolves to S3 (Exact Match: Lvalue Reference)
write(10);      // Resolves to S1 (Exact Match: Rvalue int)
write(10.0f);   // Resolves to S2 (Promotion/Conversion required)
write(r);       // Resolves to S3 (Reference match)

// Name Mangling creates unique symbols for S1, S2, S3
// e.g., _Z5writei, _Z5writed, _Z5writeRi
// (Ensures linker identifies correct function implementations)
